<template>
    <section>
        <loader :is-visible="isLoading"></loader>
        <div class="onlyd-view onlytodo_kb">
            <div class="kb-board-wrap kvminwidth">
                <div v-for="(parentItem, parentIndex) in DataArray" :key="parentIndex"
                    class="kb-board-col" v-bind:class="parentItem.className">

                    <!-- Column Header -->
                    <div class="kb-col-header" v-if="parentItem.show == 1"
                        :style="{ borderTopColor: getStatusColor(parentItem.name) }">
                        <div class="kb-col-title-row">
                            <span class="kb-col-dot" :style="{ backgroundColor: getStatusColor(parentItem.name) }"></span>
                            <span class="kb-col-name">{{ $t(parentItem.name) }}</span>
                            <span class="kb-col-count">{{ parentItem.count }}</span>
                        </div>
                    </div>

                    <div class="w-100">
                        <draggable v-bind:list="parentItem.data" class="kb-column list-group h-auto"
                            v-bind:options="{ group: 'clothes' }"
                            :data-status="parentItem.name"
                            v-on:start="onStart" v-on:end="onEnd"
                            v-on:change="ChangeStatusDrag($event, parentItem.StatusId)">
                            <div v-for="(item, index) in parentItem.data" :key="index"
                                v-bind:class="parentItem.className">
                                <div class="kb-task-card">

                                    <!-- Card Top: Priority pill + action buttons -->
                                    <div class="kb-card-top">
                                        <span v-if="item.PRIORITY_NAME && item.PRIORITY_NAME != 'null' && item.PRIORITY_NAME != null"
                                            class="kb-priority-pill"
                                            :class="{
                                                'kb-priority-critical': item.PRIORITY_NAME == 'Critical',
                                                'kb-priority-medium':   item.PRIORITY_NAME == 'Medium',
                                                'kb-priority-low':      item.PRIORITY_NAME == 'Low',
                                                'kb-priority-default':  !['Critical','Medium','Low'].includes(item.PRIORITY_NAME)
                                            }">{{ item.PRIORITY_NAME }}</span>
                                        <span v-else class="kb-priority-pill kb-priority-default">—</span>

                                        <div class="kb-card-actions">
                                            <a class="kb-icon-btn" title="View" href="javascript:;"
                                                v-on:click="ProjectQuickView(item.PROJECT_ID, item.TASK_ID, item)"
                                                v-bind:value="item.PROJECT_ID" v-bind:attr="item.PROJECT_ID">
                                                <em class="fa fa-eye text-info"></em>
                                            </a>
                                            <div class="verticle-action">
                                                <em class="fa fa-ellipsis-v action_icon_cv kb-icon-btn" aria-hidden="true" style="width:10px;"></em>
                                                <span class="action-list-box small">
                                                    <span class="list-actions fsm-list" id="action-list">
                                                        <div class="float-left">
                                                            <div class="float-left">
                                                                <a data-toggle="modal" v-on:click="ProgressDivOpen(item)"
                                                                    v-if="item.PROJECTTASKPROGRESS == 'MANUALLY_BASED'"
                                                                    checkPrivilege="yes" href="javascript:;"
                                                                    data-placement="left" style="cursor:pointer;"
                                                                    title="Update Progress"
                                                                    v-bind:class="(item.STATUS.toLowerCase() == 'completed' ? 'update actions-onclick disabled_icon' : 'update actions-onclick')">
                                                                    <em class="fa fa-pencil action-icon"></em>
                                                                    <span class="text">Update Progress</span>
                                                                </a>
                                                                <a v-if="ModuleNameAll != 'HR' && ModuleNameAll != 'Ticketing'"
                                                                    title="Request Time" data-placement="left"
                                                                    class="update actions-onclick"
                                                                    v-on:click="RequestTimeBtn(item)"
                                                                    v-bind:class="(item.IS_APPROVE_REJECT > 0 || (['ACT', 'REFPEN', 'PNPGRS'].indexOf(item.PROJECT_STATUS_ID) == -1 && item.LINKED_SOURCE_NAME == null) ? 'edit-list disabled_icon' : 'edit-list')"
                                                                    href="javascript:;">
                                                                    <em class="fa fa-reply text-dark"></em>
                                                                    <span class="text">Request Time</span>
                                                                </a>
                                                                <a title="QuickView" data-placement="left"
                                                                    v-on:click="ProjectQuickView(item.PROJECT_ID, item.TASK_ID, item)"
                                                                    v-bind:value="item.PROJECT_ID"
                                                                    class="update actions-onclick" href="javascript:;"
                                                                    v-bind:attr="item.PROJECT_ID">
                                                                    <em class="fa fa-eye text-info action-icon"></em>
                                                                    <span class="text">Quick View</span>
                                                                </a>
                                                            </div>
                                                        </div>
                                                        <em class="fa fa-times close close-action_cv cursor-pointer" aria-hidden="true"></em>
                                                    </span>
                                                </span>
                                            </div>
                                        </div>
                                    </div>

                                    <!-- Task Name -->
                                    <div class="kb-card-title">
                                        <span v-bind:title="item.TASK_NAME" class="text-capitalize text-primary">
                                            {{ item.TASK_NAME | truncate(35, '...') }}
                                        </span>
                                    </div>

                                    <!-- Project Name -->
                                    <div class="kb-card-project">
                                        <em class="fa fa-folder-o mr-1 text-muted"></em>
                                        <b class="text-capitalize text-dark">{{ item.PROJECT_NAME | truncate(28, '...') }}</b>
                                    </div>

                                    <!-- Description -->
                                    <div class="kb-card-desc" v-if="item.TASK_DESCRIPTION != null && item.TASK_DESCRIPTION != ''">
                                        <span v-html="item.TASK_DESCRIPTION"></span>
                                    </div>

                                    <!-- Dates + Notes icon -->
                                    <div class="kb-card-dates">
                                        <em class="fa fa-calendar-o mr-1"></em>
                                        <span>{{ item.START_DATE }}</span>
                                        <span class="mx-1">—</span>
                                        <span>{{ item.END_DATE }}</span>
                                        <span class="ml-1 text-muted small">{{ ModuleNameAll }}</span>
                                        <a v-if="ModuleNameAll != 'HR' && ModuleNameAll != 'Expenses'"
                                            href="javascript:;" class="text-dark ml-auto"
                                            v-on:click="openNoteListPopUp(item, index)">
                                            <em aria-hidden="true" class="fa fa-file-text-o actionicon_20" style="margin-right:5px;"></em>
                                            <span class="noti-circle noti-orange">{{ item.NOTES_COUNT == null ? 0 : item.NOTES_COUNT }}</span>
                                        </a>
                                    </div>

                                    <!-- Tracked hours -->
                                    <div class="kb-card-hours">
                                        <em class="fa fa-clock-o mr-1"></em>
                                        <span v-if="item.TRACKED_HOURS > 0" class="blue-time pl-1">{{ convertSecondsToHHMMSSNew(item.TRACKED_HOURS) }} of</span>
                                        <span class="blue-time pl-1">{{ item.ALLOCATE_HOURS }} {{ $t('Hrsshort') }}</span>
                                        <a v-if="ModuleNameAll != 'HR' && item.PROJECT_NAME != 'Ticketing'"
                                            href="javascript:;" class="text-dark ml-auto"
                                            v-on:click="ProjectQuickView(item.PROJECT_ID, item.TASK_ID, item, 'attachment')"
                                            v-bind:attr="item.PROJECT_ID">
                                            <em aria-hidden="true" class="fa fa-paperclip" style="font-size:18px;margin-right:5px;"></em>
                                            <span class="noti-circle noti-blue">{{ item.FILE_COUNT == null ? 0 : item.FILE_COUNT }}</span>
                                        </a>
                                        <a v-else-if="ModuleNameAll != 'HR' && item.PROJECT_NAME == 'Ticketing'"
                                            href="javascript:;" class="text-dark ml-auto"
                                            v-on:click="$('#DivViewDetails').data({ 'ticketId': item.LINKED_SOURCE_ID, 'status': item.STATUS, 'number': item.TASK_NAME }).dialog('open')"
                                            v-bind:attr="item.PROJECT_ID">
                                            <em aria-hidden="true" class="fa fa-paperclip" style="font-size:18px;margin-right:5px;"></em>
                                            <span class="noti-circle noti-blue">{{ item.FILE_COUNT == null ? 0 : item.FILE_COUNT }}</span>
                                        </a>
                                    </div>

                                    <!-- Tags -->
                                    <div v-if="item.TAG_NAME != ''" class="kb-card-tags">
                                        <em class="fa fa-tags mr-1 text-muted" aria-hidden="true"></em>
                                        <span class="tags-dashbm" v-for="(tagItem, k) in item.TAG_NAME" :key="k">{{ tagItem.TAG_NAME }}</span>
                                    </div>
                                    <div v-show="ModuleNameAll != 'Expenses'" v-else class="kb-card-tags text-muted">
                                        <em class="fa fa-tags mr-1" aria-hidden="true"></em>—
                                    </div>

                                    <!-- Progress bar (task completion %) -->
                                    <div class="kb-card-progress" v-if="item.PROGRESS > 0">
                                        <div class="kb-progress-wrap">
                                            <div class="kb-progress-bar"
                                                :style="{ width: item.PROGRESS + '%', backgroundColor: getStatusColor(parentItem.name) }">
                                            </div>
                                        </div>
                                        <span class="kb-progress-label">{{ item.PROGRESS }}%</span>
                                    </div>

                                    <!-- Footer: assignee avatar + comment icon -->
                                    <div class="kb-card-footer">
                                        <div class="kb-avatars">
                                            <div class="kb-avatar"
                                                :style="{ background: '#18523f' }"
                                                :title="item.NAME">
                                                {{ getInitials(item.NAME) }}
                                            </div>
                                        </div>
                                        <div class="kb-card-meta-icons">
                                            <a v-if="ModuleNameAll != 'HR'" href="javascript:;" class="kb-meta-icon"
                                                v-on:click="OpenCommentModel(item)">
                                                <em aria-hidden="true" class="fa fa-commenting-o"></em>
                                                <span class="noti-circle noti-green">{{ item.COMMENT_COUNT == null ? 0 : item.COMMENT_COUNT }}</span>
                                            </a>
                                        </div>
                                    </div>

                                    <!-- Progress circles -->
                                    <div class="kb-progress-circles border-top text-center">
                                        <div class="time">
                                            <div v-bind:class="'c100 small p' + parseInt(showTrackPercent(item), 10)">
                                                <span>{{ showTrackPercent(item) }}%</span>
                                                <div class="slice">
                                                    <div v-bind:class="{ 'bar': showTrackPercent(item) > 0 }"></div>
                                                    <div class="fill"></div>
                                                </div>
                                            </div>
                                            <span class="t-title">{{ $t('TimeLeft') }}</span>
                                        </div>
                                        <div class="Task">
                                            <div v-bind:class="'cursor-pointer c100 small green p' + parseInt(item.PROGRESS, 10)"
                                                v-on:click="ProgressDivOpen(item)"
                                                v-if="item.PROJECTTASKPROGRESS == 'MANUALLY_BASED'">
                                                <span>{{ item.PROGRESS }}%</span>
                                                <div class="slice">
                                                    <div v-bind:class="{ 'bar': item.PROGRESS > 0 }"></div>
                                                    <div class="fill"></div>
                                                </div>
                                            </div>
                                            <div v-bind:class="'c100 small green p' + parseInt(item.PROGRESS, 10)"
                                                v-if="item.PROJECTTASKPROGRESS != 'MANUALLY_BASED'">
                                                <span>{{ item.PROGRESS }}%</span>
                                                <div class="slice">
                                                    <div v-bind:class="{ 'bar': item.PROGRESS > 0 }"></div>
                                                    <div class="fill"></div>
                                                </div>
                                            </div>
                                            <span class="t-title">{{ $t('TaskProgress') }}</span>
                                        </div>
                                    </div>

                                    <!-- Timer section -->
                                    <div class="kb-timer-section border-top">
                                        <div id="TotalTime" v-if="item.AutomaticBtn" class="timerbx green"></div>
                                        <div v-if="item.RUNNING_STATUS == 'PAUS' || item.RUNNING_STATUS == 'ACT'">
                                            <button v-if="store.getTimer.statusCode == 'ACT' && store.getTimer.enableBreak != 'yes'"
                                                v-on:click="timerStopOrPause('pause', 'TimeTrack')" type="button"
                                                class="btn Timertodo btn-info kb-timer-btn">
                                                <span class="tag-name">{{ $t('Pause') }}</span>
                                            </button>
                                            <button v-if="store.getTimer.statusCode == 'PAUS' && store.getTimer.enableBreak != 'yes'"
                                                v-on:click="timerStopOrPause('resume', 'TimeTrack')" type="button"
                                                class="btn Timer btn-success kb-timer-btn">
                                                <span class="tag-name">{{ $t('Resume') }}</span>
                                            </button>
                                            <button v-if="item.RUNNING_STATUS == 'PAUS' || item.RUNNING_STATUS == 'ACT'"
                                                v-on:click="timerStopOrPause('stop', 'TimeTrack')" type="button"
                                                class="btn Timer btn-danger kb-timer-btn">
                                                <span class="tag-name">{{ $t('Stop') }}</span>
                                            </button>
                                        </div>
                                        <div v-else class="kb-timer-btns">
                                            <button :disabled="store.getTimer.trackAgent == 'silentapp' ? true : false"
                                                type="button"
                                                v-bind:class="(item.STATUS.toLowerCase() == 'completed' ? 'btn Timer manually-time inactive-disabled kb-timer-btn' : 'btn Timer manually-time kb-timer-btn')"
                                                v-on:click="manualyAddTime(item)" data-toggle="modal" href="javascript:;">
                                                <span class="tag-name"><em class="fa fa-clock-o mr-1"></em>{{ $t('AddManually') }}</span>
                                            </button>
                                            <button :disabled="store.getTimer.trackAgent == 'silentapp' ? true : false"
                                                type="button"
                                                v-bind:class="(item.STATUS.toLowerCase() == 'completed' ? 'btn Timer auto-time inactive-disabled kb-timer-btn' : 'btn Timer auto-time kb-timer-btn')"
                                                v-on:click="automaticStart(item)" data-toggle="modal" href="javascript:;">
                                                <span class="tag-name"><em class="fa fa-history mr-1"></em>{{ $t('Automatic') }}</span>
                                            </button>
                                        </div>
                                    </div>

                                </div>
                            </div>
                        </draggable>
                    </div>
                </div>
            </div>

            <div v-if="!hasRecords" class="text-center p-4 mandatory mt-2">No record(s) found.</div>


            <AddManualModal v-bind:manualData="trackerData" v-if="addManualShow" v-on:close="addManualShow = false"
                v-bind:store="store" v-on:closeUpdateModal="FetchData('kanban', '')" />
            <Comments v-bind:manualData="trackerData" v-if="commentsShow" v-on:close="commentsShow = false"
                v-bind:store="store" v-on:closeUpdateModal="FetchData('kanban', '')" />
            <RequestTimeModal v-bind:manualData="trackerData" v-if="requestShow" v-on:close="requestShow = false"
                v-bind:store="store" v-on:closeUpdateModal="FetchData('kanban', '')" />
            <Files v-if="ShowManageProjectQuickView" v-on:close="ShowManageProjectQuickView = false"
                v-bind:store="store" v-on:closeUpdateModal="FetchData('kanban', '')" />
            <AddNote v-if="showAddNoteModal" v-on:close="showAddNoteModal = false, modalNoteItem = null"
                v-bind:taskid="TaskId1" v-bind:store="store" v-on:closeUpdateModal="FetchData('kanban', '')">
                <h5 slot="header" class="modal-title">
                    {{ header }}
                </h5>
            </AddNote>
            <NoteListPopUp :userid="this.store.getUserInformation.id" reqfrom="dashboard" v-if="showNoteModal"
                v-on:close="showNoteModal = false, modalNoteTaskItem = null" v-bind:store="store">
                <h5 slot="header" class="modal-title">
                    {{ $t('Notes') }}
                </h5>
            </NoteListPopUp>
            <UpdateProgress v-if="showUpdateProgressModal" v-on:close="showUpdateProgressModal = false"
                v-bind:store="store" v-on:closeUpdateModal="FetchData('kanban', '')" />

            <modaltracklocation v-if="showTrackLocationModal" v-on:close="showTrackLocationModal = false"
                v-bind:store="store">
                <h5 slot="header">{{ $t('Location') }}</h5>
            </modaltracklocation>
        </div>
    </section>
</template>
<style>
/* ── Board wrapper ──────────────────────────────────────────── */
.onlytodo_kb .kb-board-wrap {
    display: flex;
    flex-wrap: nowrap;
    gap: 14px;
    align-items: flex-start;
    padding: 4px 2px;
}

.onlytodo_kb .kb-board-col {
    flex: 0 0 310px;
    width: 310px;
    min-width: 290px;
    font-size: 14px;
}

/* ── Column header ──────────────────────────────────────────── */
.onlytodo_kb .kb-col-header {
    border-top: 4px solid #ccc;
    border-radius: 8px 8px 0 0;
    background: #fff;
    padding: 10px 12px 8px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid #e2e5e9;
    margin-bottom: 0;
    position: sticky;
    top: 0;
    z-index: 10;
}

.onlytodo_kb .kb-col-title-row {
    display: flex;
    align-items: center;
    gap: 7px;
    min-width: 0;
    flex: 1;
}

.onlytodo_kb .kb-col-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
}

.onlytodo_kb .kb-col-name {
    font-weight: 600;
    color: #2c3e50;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    text-transform: capitalize;
}

.onlytodo_kb .kb-col-count {
    background: #e9ecef;
    color: #495057;
    font-size: 11px;
    font-weight: 600;
    border-radius: 10px;
    padding: 1px 10px;
    flex-shrink: 0;
}

/* ── Column body ────────────────────────────────────────────── */
.onlytodo_kb .kb-column {
    display: flex;
    flex-direction: column;
    background: #f4f5f7;
    border-radius: 0 0 8px 8px;
    min-height: 120px;
    padding: 10px 0 12px;
    border: 1px solid #e2e5e9;
    border-top: none;
    height: auto !important;
}

/* ── Task card ──────────────────────────────────────────────── */
.onlytodo_kb .kb-task-card {
    background: #fff;
    border: 1px solid #e2e5e9;
    border-radius: 4px;
    padding: 10px 12px;
    margin: 0 8px 8px;
    cursor: move;
    transition: box-shadow 0.15s, transform 0.15s;
    user-select: none;
    -webkit-user-select: none;
}

.onlytodo_kb .kb-task-card:hover {
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.1);
    transform: translateY(-1px);
    border-color: #c5cae9;
}

/* ── Card top: priority + actions ───────────────────────────── */
.onlytodo_kb .kb-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 7px;
}

.onlytodo_kb .kb-priority-pill {
    display: inline-block;
    font-size: 10px;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: 20px;
    border: 1px solid transparent;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.onlytodo_kb .kb-priority-critical { background: #fce4ec; color: #c62828; border-color: #f48fb180; }
.onlytodo_kb .kb-priority-medium   { background: #fff8e1; color: #e65100; border-color: #ffcc0280; }
.onlytodo_kb .kb-priority-low      { background: #e8f5e9; color: #2e7d32; border-color: #a5d6a780; }
.onlytodo_kb .kb-priority-default  { background: #f1f3f5; color: #6c757d; border-color: #dee2e6; }

.onlytodo_kb .kb-card-actions {
    display: flex;
    align-items: center;
    gap: 2px;
}

.onlytodo_kb .kb-icon-btn {
    width: 24px;
    height: 24px;
    border-radius: 4px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #868e96;
    cursor: pointer;
    transition: background 0.15s;
}

.onlytodo_kb .kb-icon-btn:hover { background: #f1f3f5; }

/* ── Card title ─────────────────────────────────────────────── */
.onlytodo_kb .kb-card-title {
    font-weight: 500;
    color: #2c3e50;
    line-height: 1.4;
    margin-bottom: 4px;
}

/* ── Project name row ───────────────────────────────────────── */
.onlytodo_kb .kb-card-project {
    font-size: 12px;
    color: #495057;
    margin-bottom: 5px;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
}

/* ── Description snippet ────────────────────────────────────── */
.onlytodo_kb .kb-card-desc {
    font-size: 12px;
    color: #6c757d;
    line-height: 1.45;
    margin-bottom: 6px;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    line-clamp: 2;
    overflow: hidden;
    word-break: break-word;
}

/* ── Dates row ──────────────────────────────────────────────── */
.onlytodo_kb .kb-card-dates {
    font-size: 12px;
    color: #42484e;
    margin-bottom: 5px;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
}

/* ── Hours row ──────────────────────────────────────────────── */
.onlytodo_kb .kb-card-hours {
    font-size: 12px;
    color: #42484e;
    margin-bottom: 5px;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
}

/* ── Tags row ───────────────────────────────────────────────── */
.onlytodo_kb .kb-card-tags {
    font-size: 12px;
    color: #495057;
    margin-bottom: 5px;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 3px;
}

/* ── Progress bar ───────────────────────────────────────────── */
.onlytodo_kb .kb-card-progress {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 8px;
}

.onlytodo_kb .kb-progress-wrap {
    flex: 1;
    height: 5px;
    background: #e9ecef;
    border-radius: 3px;
    overflow: hidden;
}

.onlytodo_kb .kb-progress-bar {
    height: 100%;
    border-radius: 3px;
    transition: width 0.3s ease;
    min-width: 2px;
}

.onlytodo_kb .kb-progress-label {
    font-size: 10px;
    color: #868e96;
    white-space: nowrap;
    flex-shrink: 0;
}

/* ── Card footer: avatars + meta icons ──────────────────────── */
.onlytodo_kb .kb-card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0;
    padding-top: 4px;
}

.onlytodo_kb .kb-avatars { display: flex; }

.onlytodo_kb .kb-avatar {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    color: #fff;
    font-size: 10px;
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #fff;
    margin-right: -4px;
    text-transform: uppercase;
}

.onlytodo_kb .kb-card-meta-icons {
    display: flex;
    align-items: center;
    gap: 8px;
}

.onlytodo_kb .kb-meta-icon {
    font-size: 14px;
    color: #404040;
    display: inline-flex;
    align-items: center;
    gap: 3px;
    text-decoration: none;
}

/* ── Progress circles section ───────────────────────────────── */
.onlytodo_kb .kb-progress-circles {
    display: flex;
    justify-content: center;
    gap: 16px;
    padding: 8px 0 4px;
}

/* ── Timer section ──────────────────────────────────────────── */
.onlytodo_kb .kb-timer-section {
    padding: 8px 0 2px;
    text-align: center;
}

.onlytodo_kb .kb-timer-btns {
    display: flex;
    gap: 4px;
    justify-content: center;
}

.onlytodo_kb .kb-timer-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48%;
    min-width: 120px;
    font-size: 12px;
}

.onlytodo_kb .kb-timer-section .Timer,
.onlytodo_kb .kb-timer-section .Timertodo {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48%;
    min-width: 120px;
    font-size: 12px;
}

/* ── Drag states ────────────────────────────────────────────── */
.onlytodo_kb .ghost-task {
    opacity: 0.35;
    background: #e3f2fd;
    border: 2px dashed #90caf9;
    border-radius: 6px;
}
</style>
<script>
import DataService from '../../services/DataService';
import moment from 'moment';
import {
    getSecondsFromDate
} from "@/assets/common/vue-common.js";
import AddManualModal from "../../components/Modal/AddManualModal.vue";
import Comments from "../../components/Modal/Comments.vue";
import RequestTimeModal from "../../components/Modal/RequestTimeModal.vue";
import Files from '@/components/Modal/todoListFiles.vue';
import AddNote from "@/components/Modal/modalAddNote.vue";
import UpdateProgress from '@/components/Modal/updateProgress.vue';
import modaltracklocation from "@/components/Modal/modaltracklocation.vue";
import NoteListPopUp from "@/components/Modal/modalNoteListPopUp.vue";
import {
    userTimerInfo
} from "@/stores/TimeTrack.js";

export default {
    name: "ToDo List Canban View",
    components: {
        AddManualModal,
        Comments,
        RequestTimeModal,
        Files,
        NoteListPopUp,
        AddNote,
        UpdateProgress,
        modaltracklocation,

    },
    props: {
        status: {
            type: String,
            required: false
        },
        module: {
            type: String,
            required: true,
        }
    },
    setup() {
        const store = userTimerInfo();
        return {
            store
        }
    },
    data() {
        return {
            ShowManageProjectQuickView: false,
            showTrackLocationModal: false,
            showUpdateProgressModal: false,
            toDoList: [],
            Timer: '',
            globalTime: '',
            secondsPerMinute: 60,
            minutesPerHour: 60,
            Date: '',
            noRecordToDoList: false,
            PageNumber: 1,
            PageSize: 10,
            SortBy: '',
            SortExp: '',
            PageSizeOption: null,
            CurrentPage: 1,
            TotalPages: 0,
            projectName: '',
            Status: '',
            //EndDateForSearch: '',
            TotalRecords: 0,
            TRACKED_HOURS: '',
            PROJECT_ID: '',
            TASK_ID: '',
            PROGRESS: '',
            PendingRecords: 0,
            ProgressRecords: 0,
            OverdueRecords: 0,
            UpcomingRecords: 0,
            CompletedRecords: 0,
            cardViewData: [],
            TagData: [],
            TrackId: 0,
            pendingData: [],
            inprogressData: [],
            comData: [],
            MaxCount: 0,
            showNoteModal: false,
            modalNoteTaskItem: null,
            showAddNoteModal: false,
            modalNoteItem: null,
            header: '',
            TaskId1: null,
            ProjectId: null,
            ModuleName: 'TODOLIST',
            ModuleNameAll: '',
            isLoading: false,
            isActiveWeeklyStatus: true,
            trackerData: {
                projectId: 0,
                trackDescription: "",
                taskId: 0,
                isBillable: 0,
                format: false,
                date: null,
                trackId: 0,
                startTime: moment().format("YYYY-MM-DD HH:mm:ss"),
                stopTime: moment().format("YYYY-MM-DD HH:mm:ss"),
                companyId: null,
                currentDate: moment().format("YYYY-MM-DD HH:mm:ss"),
                trackAgent: "web",
                timerStatus: "start",
                CreatedBy: this.store.getUserInformation.id,
                createdBy: this.store.getUserInformation.id,
                linkedTrackId: null,
                totalHours: 0,
                timeformat: 12,
                TagIds: "",
                isForcedUpdate: null,
                type: "TimeTrack",
                trackType: "TimeTrack",
                BreakDate: null,
                BreakName: null,
                BreakId: '',
                BreakStartTime: 0,
                Shift_ID: 0,
                SelectedDate: "",
                Break_Shift: "",
            },
            series: [],
            series1: [],
            chartOptions: {

            },
            chartOptions1: {

            },
            seriesbar: [],
            chartOptionsBar: {},

            addManualShow: false,
            commentsShow: false,
            requestShow: false,
            fromData: {},
            buttonIndex: '',
            isActiveActionButton: false,
            DataArray: [],
            DraggedFromElementStatus: "",
            DraggedToElementStatus: "",
            DraggedElementTaskId: null,
            DraggedElementStatus: null,
            projectId:null,
            hasRecords: false
        }
    },
    created() {    
        this.projectId = this.$route.params.projectId;
        if (this.projectId == undefined) {
            this.projectId = '';
        }    
        this.StatusDropdown();
        this.Status = this.status;
        this.FetchData();
        Object.assign(this.fromData, this.trackerData)
        this.store.getTimerInfo();
    },
    mounted() {
        const canbanScroll = document.querySelector('.onlyd-view');
        let previousScrollTop = canbanScroll.scrollTop;
        canbanScroll.addEventListener('scroll', e => {
            const currentScrollTop = canbanScroll.scrollTop;

            if (currentScrollTop + canbanScroll.clientHeight >= canbanScroll.scrollHeight) {
                if (this.TotalPages > this.PageNumber) {
                    this.PageNumber = this.PageNumber + 1;
                    this.FetchData('scroll');
                }
                canbanScroll.scrollTop = 1810;
            } else if (currentScrollTop == 0) {                
                if (this.PageNumber > 1) {
                    this.PageNumber = this.PageNumber - 1;
                    this.FetchData('scroll');
                }
            }
            previousScrollTop = currentScrollTop;
        });
    },
    methods: {
        StatusDropdown: function () {
            var vm = this;
            var url = "langCode=en&statusType=Project&hasGlobal=1";
            DataService.StatusDropdown(url).then(function (response) {
                if (response.data != null && response.data != "") {
                    vm.StatusList = response.data.result.data;
                    vm.pendingData = $.grep(vm.StatusList, function (element, index) {
                        return element.STATUS_CODE == 'REFPEN';
                    });
                    vm.inprogressData = $.grep(vm.StatusList, function (element, index) {
                        return element.STATUS_CODE == 'PNPGRS';
                    });
                    vm.comData = $.grep(vm.StatusList, function (element, index) {
                        return element.STATUS_CODE == 'STATUS_DONE';
                    });
                }
            });
        },
        ShowDataArray: function () {
            var vm = this;
            var array = [];
            array.push({
                name: "overdue",
                count: 0,
                data: [],
                show: 1,
                className: "canceled",
                SortIcon: "fa-sort-alpha-desc",
                StatusId: 0
            });
            array.push({
                name: "pending",
                count: 0,
                data: [],
                show: 1,
                className: "pending",
                SortIcon: "fa-sort-alpha-desc",
                StatusId: vm.pendingData[0].STATUS_ID
            });
            array.push({
                name: "inprogress",
                count: 0,
                data: [],
                show: 1,
                className: "overdue",
                SortIcon: "fa-sort-alpha-desc",
                StatusId: vm.inprogressData[0].STATUS_ID
            });
            array.push({
                name: "completed",
                count: 0,
                data: [],
                show: 1,
                className: "upcoming",
                SortIcon: "fa-sort-alpha-desc",
                StatusId: vm.comData[0].STATUS_ID
            });
            array.push({
                name: "upcoming",
                count: 0,
                data: [],
                show: 1,
                className: "inactive",
                SortIcon: "fa-sort-alpha-desc",
                StatusId: 0
            });
            this.DataArray = array;
        },

        async FetchData(e) {            
            var vueObj = this;
            vueObj.isLoading = true;
            if (e !== 'scroll') {
                vueObj.DataArray.forEach(item => item.data = []);
                vueObj.toDoList = [];
                vueObj.TagData = [];
                vueObj.hasRecords = false;
            }
            let url = `pageSize=${this.PageSize}&pageNumber=${this.PageNumber}&sortBy=${this.SortBy}&sortExp=${this.SortExp}&projectId=${vueObj.projectId}&type=kanban`;
            if (this.module) {
                url += `&moduleNameForSearch=${this.module}`;
            } else {
                url += `&moduleNameForSearch=''`;
            }

            if (this.Status) {
                url += `&status=${this.Status}`;
            } else {
                url += `&status=`;
            }
            try {    
                const response = await DataService.GetToDoListing(url);
                var responseData = response.data.result.DATA;
                vueObj.ShowDataArray();
                if (responseData && responseData.length) {
                    vueObj.toDoList = responseData;
                    vueObj.DataArray.forEach(item => {
                        const name = item.name;
                        switch (item.name) {
                            case 'overdue':
                                item.count = vueObj.toDoList[0].OVERDUERECORDS || 0;
                                break;
                            case 'pending':
                                item.count = vueObj.toDoList[0].PENDINGRECORDS || 0;
                                break;
                            case 'inprogress':
                                item.count = vueObj.toDoList[0].PROGRESSRECORDS || 0;
                                break;
                            case 'upcoming':
                                item.count = vueObj.toDoList[0].UPCOMINGRECORDS || 0;
                                break;
                            case 'completed':
                                item.count = vueObj.toDoList[0].COMPLETEDRECORDS || 0;
                                break;
                            default:
                                item.count = 0;
                                break;
                        }
                        const data = responseData.filter(element => element.STATUS.toLowerCase() === name);
                         item.data = data;
                    });
                    vueObj.hasRecords = vueObj.DataArray.some(item => item.data.length > 0);
                    vueObj.TotalPages = Math.ceil(vueObj.toDoList[0].TOTALRECORDS / vueObj.PageSize);
                    vueObj.CurrentPage = vueObj.PageNumber;
                    vueObj.TagData = response.data.result.TAGDATA;
                }

            } catch (error) {
                console.error("Error fetching data:", error);
            } finally {
                vueObj.isLoading = false;
            }
        },
        OpenCommentModel(item) {
            var vm = this;
            Object.assign(vm.trackerData, vm.fromData)
            vm.trackerData.MESSAGE_BOARD_ID = item.MESSAGE_BOARD_ID
            vm.trackerData.totalHours = item.TRACKED_HOURS
            vm.trackerData.projectId = item.PROJECT_ID
            vm.trackerData.taskId = item.TASK_ID
            vm.trackerData.TASK_NAME = item.TASK_NAME
            vm.trackerData.trackDescription = item.TASK_DESCRIPTION
            this.commentsShow = true
        },
        RequestTimeBtn(item) {
            var vm = this;
            Object.assign(vm.trackerData, vm.fromData)
            vm.trackerData.MESSAGE_BOARD_ID = item.MESSAGE_BOARD_ID
            vm.trackerData.trackId = 0
            vm.trackerData.totalHours = item.TRACKED_HOURS
            vm.trackerData.projectId = item.PROJECT_ID
            vm.trackerData.taskId = item.TASK_ID
            vm.trackerData.TASK_NAME = item.TASK_NAME
            vm.trackerData.trackDescription = item.TASK_DESCRIPTION
            this.requestShow = true

        },
        automaticStart(item) {
            var vm = this;
            Object.assign(vm.trackerData, vm.fromData)
            vm.trackerData.startTime = moment().format("YYYY-MM-DD HH:mm:ss")
            vm.trackerData.stopTime = moment().format("YYYY-MM-DD HH:mm:ss")
            vm.trackerData.trackId = 0
            vm.trackerData.totalHours = 0
            vm.trackerData.projectId = item.PROJECT_ID
            vm.trackerData.taskId = item.TASK_ID
            vm.trackerData.trackDescription = item.TASK_DESCRIPTION
            if (this.store.getTimer.statusCode) {
                vm.confirmR(vm.$t("PreviouseStopNewRunTime"), true, (vm.$t("Send") + "  " + vm.$t("Records")), async function () {
                    await vm.timerStopOrPause('stop', 'TimeTrack');
                    if (vm.store.getTimerRunResponse.userMsg == 'stop') {
                        await vm.store.submitProjectInfo(vm.trackerData, vm)
                        vm.FetchData()
                        vm.store.getTimerInfo();
                        vm.urlChange()
                    }
                })
            } else {
                vm.confirmR(vm.$t("ConfirmTimerContinue"), true, (vm.$t("Send") + "  " + vm.$t("Records")), async function () {
                    await vm.store.submitProjectInfo(vm.trackerData, vm)
                    if (vm.store.getTimerRunResponse.trackId != 0 && vm.store.getTimerRunResponse.trackId) {
                        await vm.store.startTimer()
                        vm.FetchData()
                        vm.store.getTimerInfo();
                        vm.urlChange()
                    }
                })
            }
        },
        urlChange() {
            const query = Object.assign({}, this.$route.query);
            query.reload = 'reload'
            this.$router.replace({
                query
            });
        },
        ToggleActionButton(index) {
            this.isActiveActionButton = !this.isActiveActionButton;
            if (index === this.buttonIndex) {
                this.buttonIndex = ''; 
            } else {
                this.buttonIndex = index
            }
        },
        manualyAddTime(item) {
            var vm = this;
            Object.assign(vm.trackerData, vm.fromData)
            vm.trackerData.trackId = 0
            vm.trackerData.totalHours = 0
            vm.trackerData.projectId = item.PROJECT_ID
            vm.trackerData.taskId = item.TASK_ID
            vm.trackerData.trackDescription = item.TASK_DESCRIPTION
            vm.trackerData.linkedTrackId = 0
            if (this.store.getTimer.statusCode) {
                vm.confirmR(vm.$t("AddManualWhenTimerAllreadyRunning"), true, (vm.$t("Send") + "  " + vm.$t("Records")), async function () {
                    await vm.timerStopOrPause('stop', 'TimeTrack');
                    if (vm.store.getTimerRunResponse.userMsg == 'stop') {
                        vm.addManualShow = true
                    }
                })
            } else {
                vm.addManualShow = true
            }
        },
        async timerStopOrPause(status, type) {
            this.store.getTimer.CreatedBy = this.store.getUserInformation.id
            this.store.getTimer.createdBy = this.store.getUserInformation.id
            this.store.getTimer.currentDate = moment().format('YYYY-MM-DD HH:mm:ss')
            this.store.getTimer.timerStatus = status
            this.store.getTimer.trackType = type
            this.store.getTimer.type = type
            this.store.trackAgent = "web"
            if (status == 'pause' && type == 'TimeTrack') {
                let countResumeInSeconds = 0
                this.store.$state.timerCountInSec = moment(new Date(this.store.getTimer.dateStop), "DD/MM/YYYY HH:mm:ss").format("DD-MM-YYYY") == "01-01-1950" ?
                    getSecondsFromDate({
                        startDate: this.store.getTimer.dateStart,
                        endDate: moment()
                    }, 'seconds') : countResumeInSeconds + parseInt(this.store.getTimer.resumeHours)
                this.store.getTimer.stopTime = moment().format('YYYY-MM-DD HH:mm:ss')
                this.store.getTimer.totalHours = this.store.$state.timerCountInSec
                await this.store.submitProjectInfo(this.store.getTimer, this)
                await this.store.getTimerInfo();
                this.store.stopTimer()
            } else if (status == 'stop' && type == 'TimeTrack') {
                this.store.getTimer.stopTime = moment().format('YYYY-MM-DD HH:mm:ss')
                this.store.getTimer.startTime = moment().format('YYYY-MM-DD HH:mm:ss')
                this.store.getTimer.totalHours = this.store.$state.timerCountInSec
                await this.store.submitProjectInfo(this.store.getTimer, this)
                await this.store.getTimerInfo();

                this.store.stopTimer()
                this.store.$state.timerCountInSec = 0
                this.store.$state.timerClock = "00:00:00"
            } else if (status == 'resume' && type == 'TimeTrack') {
                this.store.getTimer.startTime = moment().format('YYYY-MM-DD HH:mm:ss')
                await this.store.submitProjectInfo(this.store.getTimer, this)
                await this.store.getTimerInfo();
                this.store.$state.timerCountInSec = parseInt(this.store.getTimer.resumeHours)
                this.store.startTimer()
            }
            this.urlChange();
            this.FetchData();           
        },
        toggleWeeklyStatus() {
            if (!this.isActiveWeeklyStatus) {
                this.isActiveWeeklyStatus = true;
            } else {
                this.isActiveWeeklyStatus = false;
            }
        },
        showTrackPercent: function (item) {
            var percent = 0;
            percent = (item.TRACKED_HOURS / ((item.ALLOCATE_HOURS) * 3600));
            percent = percent * 100;
            percent = parseFloat(percent, 10).toFixed(1);
            if (percent <= 0 || isNaN(percent) || percent.toLowerCase() == 'infinity') {
                percent = 100;
            } else {
                percent = 100 - percent;
            }
            if (Math.sign(percent) < 0) {
                percent = 0;
            }
            percent = Math.round(parseFloat(percent, 10));
            return percent;
        },
        formatOnlyMonthYearWithComma: function (value) {
            if (value) {
                return moment(value).format('MMM') + ', ' + moment(value).format('YYYY');
            }
        },
        formatOnlyDate: function (value) {
            if (value) {
                return moment(value).format('DD');
            }
        },
        convertSecondsToHHMMSS: function (intSecondsToConvert) {
            var hours = this.convertHours(intSecondsToConvert);
            var minutes = this.getRemainingMinutes(intSecondsToConvert);
            minutes = minutes == 60 ? "00" : minutes;
            if (hours < 10) hours = "0" + hours;
            if (minutes < 10) minutes = "0" + minutes;
            return hours + ":" + minutes;
        },
        calculateWeekHoursAVG: function (totalHours, days) {
            var avgPerWeekHours = Math.floor(totalHours / days);
            if (isNaN(avgPerWeekHours)) {
                avgPerWeekHours = 0;
            }
            return avgPerWeekHours
        },
        convertSecondsToHHMMSSNew: function (intSecondsToConvert) {
            var hours = this.convertHours(intSecondsToConvert);
            var minutes = this.getRemainingMinutes(intSecondsToConvert);
            minutes = minutes == 60 ? "00" : minutes;
            var seconds = this.getRemainingSeconds(intSecondsToConvert);
            if (hours < 10) hours = "0" + hours;
            if (minutes < 10) minutes = "0" + minutes;
            if (seconds < 10) seconds = "0" + seconds;
            return hours + ":" + minutes + ":" + seconds;
        },
        convertHours: function (intSeconds) {
            var minutes = this.convertMinutes(intSeconds);
            var hours = Math.floor(minutes / this.minutesPerHour);
            return hours
        },
        convertHoursTwoDecimal: function (intSeconds) {
            var minutes = this.convertMinutes(intSeconds);
            var hours = (minutes / this.minutesPerHour).toFixed(2);
            return hours
        },
        convertMinutes: function (intSeconds) {
            return Math.floor(intSeconds / this.secondsPerMinute)
        },
        getRemainingMinutes: function (intSeconds) {
            var intTotalMinutes = this.convertMinutes(intSeconds);
            return intTotalMinutes % this.minutesPerHour
        },
        getRemainingSeconds: function (intTotalSeconds) {
            return intTotalSeconds % this.secondsPerMinute
        },
        splitTimeZone: function (item) {
            var fullname = item.split(' ');
            return fullname[0];
        },
        splitTags: function (item) {
            return (item != null) ? item.split(",") : [];
        },
        convertSecondsToHH: function (intSecondsToConvert) {
            var hours = this.convertHoursTwoDecimal(intSecondsToConvert);
            if (hours < 10) hours = "0" + hours;
            return hours + " hrs "
        },
        checkMove: function (evt) {
            this.DraggedFromElementStatus = evt.draggedContext.element.STATUS;
            if (String(evt.draggedContext.element.STATUS).toLowerCase() == "completed" || String(evt.draggedContext.element.STATUS).toLowerCase() == "upcoming") {
                return false;
            }
            else {
                return true;
            }
        },
        onStart: function (evt) {
            try {
                this.DraggedFromElementStatus = evt.item._underlying_vm_.STATUS;
            }
            catch (ex) {
               
            }
            if ($(evt.srcElement).attr("status") == $(evt.target).attr("status")) {
                return false;
            }
        },
        onEnd: function (evt) {
            this.DraggedToElementStatus = evt.to.getAttribute("data-status");
            
            if (typeof (this.DraggedElementStatus) == "undefined" || this.DraggedElementStatus == "" || this.DraggedElementStatus == null || this.DraggedElementStatus == "0") {
                this.DraggedElementStatus = $(evt.to).closest(".cards-content").attr("data-statusid");
                
            }
            this.UpdateStatusDragDrop();
        },
        ChangeStatusDrag: function (evt, status) {
            var vm = this;
            if (typeof (evt.added) != "undefined") {
                vm.DraggedElementTaskId = evt.added.element.TASK_ID;
                vm.DraggedElementStatus = status;
            }
        },
        UpdateStatusDragDrop: function () {
            var vm = this;
            var canMove = false;
            var draggedFromElementStatus = String(vm.DraggedFromElementStatus).toLocaleLowerCase();
            var draggedToElementStatus = String(vm.DraggedToElementStatus).toLocaleLowerCase();           
            if (draggedFromElementStatus == "" || vm.DraggedElementTaskId == null) {
                return false;
            }
            if (draggedFromElementStatus == "overdue" && (draggedToElementStatus == "inprogress" || draggedToElementStatus == "completed")) {
                canMove = true;
            }
            else if (draggedFromElementStatus == "pending" && (draggedToElementStatus == "inprogress" || draggedToElementStatus == "completed")) {
                canMove = true;
            }
            else if (draggedFromElementStatus == "inprogress" && draggedToElementStatus == "completed") {
                canMove = true;
            }
            if (canMove) {
                var VarObject = {
                    ID: vm.DraggedElementTaskId,
                    StatusId: vm.DraggedElementStatus,
                    IsFor: "TODOKANBANLISTING"
                };
                var objectPostString = JSON.stringify(VarObject);
                DataService.UpdateStatus(objectPostString).then(function (response) {
                    vm.isLoading = true;                   
                    if (response.data != null) {
                        if (response.data.status === "Success") {
                            //location.reload(true);
                            vm.DataArray.data = [];
                            vm.PageNumber = 1;
                            $("#hdfStartIndex").val(1);
                            $("#hdfEndIndex").val(100);
                            vm.ShowAlert(vm.$t("RecordsUpdatedSuccessfully"), "success", true, vm.$t("Alert"));
                            vm.FetchData();
                        }
                        else {
                            vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t("Alert"));
                            vm.FetchData();
                        }
                    }
                    else {
                        vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t("Alert"));
                        vm.FetchData();
                    }
                    vm.isLoading = false;
                    vm.DraggedElementTaskId = null;
                });
            }
            else {
                vm.DraggedElementTaskId = null;
                vm.FetchData("kanban", null);
                vm.ShowAlert(vm.$t("Dragging"), "warning", true, vm.$t("Alert"));
            }
            vm.isLoading = false;
        },
        openNoteListPopUp: function (item, index) {
            var vm = this;
            vm.showNoteModal = true;
            vm.modalNoteTaskItem = item;
            this.ProjectId = item.PROJECT_ID;
        },
        ProjectQuickView(project_id, task_id, item, type) {
            this.ShowManageProjectQuickView = true;
            this.modalProjectId = project_id;
            this.modalTaskId = task_id;
        },
        openProjectNoteModel: function (item, taskid) {
            if (item != '' && item != null) {
                //if (GetPrivilege("/Project/EditNote", true, false)) {
                this.TaskId1 = taskid;
                //this.ProjectId = item.PROJECT_ID;
                this.showAddNoteModal = (this.showAddNoteModal == true) ? false : true;
                this.modalNoteItem = item;
                this.header = this.$t('EditNotes');
                //}
            } else {
                // if (GetPrivilege("/Project/AddNoteInProject", true, false)) {
                this.TaskId1 = taskid;
                //this.ProjectId = item.PROJECT_ID;
                this.showAddNoteModal = (this.showAddNoteModal == true) ? false : true;
                this.header = this.$t('AddNotes');
                // }
            }
        },
        ProgressDivOpen: function (item) {
            var vm = this;
            vm.showUpdateProgressModal = true;
            item.StopTimerBtn = true;
            item.UpdateProgress = true;
            vm.TRACKED_HOURS = this.convertSecondsToHHMMSSNew(item.TRACKED_HOURS);
            vm.TASK_ID = item.TASK_ID;
            vm.PROGRESS = item.PROGRESS;
        },
        trackLocation: function (trackId) {
            this.TrackId = trackId;
            this.showTrackLocationModal = true;
        },
        FormatDateToTime(Getdate, formattype) {
            return moment(Getdate).format(formattype);
        },
        getStatusColor(name) {
            var colors = {
                overdue: '#dc3545',
                pending: '#fd7e14',
                inprogress: '#17a2b8',
                completed: '#28a745',
                upcoming: '#6c757d'
            };
            return colors[name] || '#6c757d';
        },
        getInitials(name) {
            if (!name) return '?';
            var parts = String(name).trim().split(/\s+/);
            return ((parts[0] ? parts[0].charAt(0) : '') + (parts[1] ? parts[1].charAt(0) : '')).toUpperCase() || '?';
        }
    },

}
</script>
